async function fetchStats(startDate, endDate, childId) {
    // Reusing fetchExpenses logic
    const { data: all } = await fetchExpenses(undefined, {
        startDate,
        endDate,
        childId
    });
    let totalExpenses = 0;
    let totalIncome = 0;
    let totalDue = 0;
    let dueCount = 0;
    const byCategory = {};
    const incomeByCategory = {};
    all.forEach((e)=>{
        const val = Number(e.amount);
        const catName = e.category || "Uncategorized";
        if (e.type === "INCOME") {
            totalIncome += val;
            incomeByCategory[catName] = (incomeByCategory[catName] || 0) + val;
        } else if (e.type === "DUE") {
            totalDue += val;
            dueCount++;
        } else {
            totalExpenses += val;
            byCategory[catName] = (byCategory[catName] || 0) + val;
        }
    });
    return {
        totalExpenses,
        totalIncome,
        totalDue,
        dueCount,
        balance: totalIncome - totalExpenses,
        byCategory,
        incomeByCategory
    };
}
